:root {
  --bg-card: #0d2b45;
  --bg-header: #0a2035;
  --bg-stats: #0f3356;
  --bg-detail: #112d4a;
  --bg-footer: #0a2035;
  --accent-teal: #2ec4b6;
  --accent-coral: #ff6b6b;
  --accent-gold: #ffd166;
  --accent-green: #06d6a0;
  --text-primary: #e8f4fd;
  --text-muted: #7fb3d3;
  --tag-calm-bg: #1a4a6e;
  --tag-calm-text: #7ecfef;
  --tag-current-bg: #1a3d5c;
  --tag-current-text: #a0c8e8;
  --tag-sunny-bg: #3d2e0a;
  --tag-sunny-text: #ffd166;
  --tag-creature-bg: #0f3a30;
  --tag-creature-text: #06d6a0;
  --tank-bar-bg: #1a3d5c;
  --cert-bg: #2ec4b6;
  --cert-text: #0d2b45;
  --star-filled: #ffd166;
  --star-empty: #2a4d6e;
  --border-color: #1e4d73;
}

.dive-log {
  background-color: var(--bg-card);
  border-radius: 14px;
  border: 1px solid var(--border-color);
  width: 480px;
  overflow: hidden;
  font-size: 14px;
  color: var(--text-primary);
}

.dive-header {
  background-color: var(--bg-header);
  padding: 12px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid var(--border-color);
}

.dive-badge {
  background-color: var(--accent-teal);
  color: var(--bg-card);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: 6px;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

.dive-title {
  flex: 1;
}

.dive-title h2 {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.dive-location {
  font-size: 12px;
  color: var(--text-muted);
}

.dive-rating {
  display: flex;
  gap: 2px;
}

.star {
  font-size: 14px;
  color: var(--star-empty);
}

.star.filled {
  color: var(--star-filled);
}

.dive-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  background-color: var(--bg-stats);
  border-bottom: 1px solid var(--border-color);
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 8px;
  border-right: 1px solid var(--border-color);
}

.stat:last-child {
  border-right: none;
}

.stat-value {
  font-size: 22px;
  font-weight: 700;
  color: var(--accent-teal);
  line-height: 1;
}

.stat-unit {
  font-size: 12px;
  font-weight: 400;
  color: var(--text-muted);
  margin-left: 1px;
}

.stat-label {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 4px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.dive-details {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  background-color: var(--bg-detail);
  border-bottom: 1px solid var(--border-color);
  padding: 12px 16px;
  gap: 12px;
}

.detail-col h3 {
  margin: 0 0 8px 0;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

.tag-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.tag {
  display: inline-block;
  font-size: 12px;
  font-weight: 500;
  padding: 3px 8px;
  border-radius: 4px;
  width: fit-content;
}

.tag.calm {
  background-color: var(--tag-calm-bg);
  color: var(--tag-calm-text);
}

.tag.current {
  background-color: var(--tag-current-bg);
  color: var(--tag-current-text);
}

.tag.sunny {
  background-color: var(--tag-sunny-bg);
  color: var(--tag-sunny-text);
}

.tag.creature {
  background-color: var(--tag-creature-bg);
  color: var(--tag-creature-text);
}

.dive-footer {
  background-color: var(--bg-footer);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  gap: 14px;
}

.tank-info {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
}

.tank-label {
  font-size: 11px;
  color: var(--text-muted);
  white-space: nowrap;
}

.tank-bar {
  flex: 1;
  height: 8px;
  background-color: var(--tank-bar-bg);
  border-radius: 4px;
  overflow: hidden;
}

.tank-fill.start {
  width: 100%;
  height: 100%;
  background-color: var(--accent-green);
  border-radius: 4px;
}

.tank-fill.end {
  width: 30%;
  height: 100%;
  background-color: var(--accent-coral);
  border-radius: 4px;
}

.tank-psi {
  font-size: 11px;
  color: var(--text-muted);
  white-space: nowrap;
}

.cert-badge {
  background-color: var(--cert-bg);
  color: var(--cert-text);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
  letter-spacing: 0.04em;
  white-space: nowrap;
}
